/**
 * pandwind scanner — extracts the classes used by `tw()` calls and writes them
 * to a safelist file that Tailwind's file scanner can see.
 *
 * Tailwind v4 scans source files on disk for literal class candidates, so
 * classes composed at runtime by `tw()` are invisible to it. This script
 * statically evaluates every `tw({ ... })` call in the app source (using the
 * *same* typed `tw` instance the app imports), collects the resulting class
 * strings, and writes them into a generated file:
 *
 * ```ts
 * export const pandwindSafelist = ["bg-sky-600", "sm:flex", ...] as const;
 * ```
 *
 * The file lives inside the scanned source tree, so Tailwind generates CSS for
 * exactly those classes — and nothing more.
 *
 * Usage:
 *   tsx collect.ts [tw-entry] [src-dir] [out-file]
 *
 * All paths are resolved relative to the current working directory.
 */

import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";
import ts from "typescript";

const SOURCE_EXTENSIONS = /\.(ts|tsx)$/;

function walk(dir: string, files: string[] = []): string[] {
	for (const entry of readdirSync(dir, { withFileTypes: true })) {
		const path = join(dir, entry.name);
		if (entry.isDirectory()) walk(path, files);
		else if (SOURCE_EXTENSIONS.test(entry.name)) files.push(path);
	}
	return files;
}

/**
 * Statically evaluate a `tw()` argument. Only pure literal expressions are
 * supported; anything else (variables, spreads, template expressions) makes
 * the call invisible to the scanner — same limitation as dynamic class names
 * in plain Tailwind.
 */
function evalValue(node: ts.Expression): unknown {
	if (ts.isStringLiteral(node) || ts.isNoSubstitutionTemplateLiteral(node))
		return node.text;
	if (ts.isNumericLiteral(node)) return Number(node.text);
	if (node.kind === ts.SyntaxKind.TrueKeyword) return true;
	if (node.kind === ts.SyntaxKind.FalseKeyword) return false;
	if (
		ts.isPrefixUnaryExpression(node) &&
		node.operator === ts.SyntaxKind.MinusToken &&
		ts.isNumericLiteral(node.operand)
	) {
		return -Number(node.operand.text);
	}
	if (ts.isArrayLiteralExpression(node)) {
		return node.elements.map(evalValue);
	}
	if (ts.isObjectLiteralExpression(node)) {
		const styles: Record<string, unknown> = {};
		for (const property of node.properties) {
			if (!ts.isPropertyAssignment(property)) return undefined;
			const { name } = property;
			const key =
				ts.isIdentifier(name) ||
				ts.isStringLiteral(name) ||
				ts.isNumericLiteral(name)
					? name.text
					: undefined;
			if (key === undefined) return undefined;
			const value = evalValue(property.initializer);
			if (value === undefined) return undefined;
			styles[key] = value;
		}
		return styles;
	}
	return undefined;
}

/**
 * Collect every class string produced by `tw()` calls across `files`.
 *
 * @param files source files to scan
 * @param twEntry absolute path to the app's generated `tw.ts` — its exported
 *   `tw` is the exact instance the app uses, so variant metadata matches.
 */
export async function collectTwClasses(
	files: string[],
	twEntry: string,
): Promise<string[]> {
	const { tw } = (await import(twEntry)) as { tw: (styles: unknown) => string };
	const classes = new Set<string>();

	for (const file of files) {
		const source = ts.createSourceFile(
			file,
			readFileSync(file, "utf8"),
			ts.ScriptTarget.Latest,
			true,
			file.endsWith(".tsx") ? ts.ScriptKind.TSX : ts.ScriptKind.TS,
		);

		const visit = (node: ts.Node) => {
			if (
				ts.isCallExpression(node) &&
				ts.isIdentifier(node.expression) &&
				node.expression.text === "tw"
			) {
				for (const argument of node.arguments) {
					const styles = evalValue(argument);
					if (styles === undefined) continue;
					try {
						for (const className of tw(styles).split(" ")) {
							if (className) classes.add(className);
						}
					} catch {
						// Unrepresentable call (e.g. a modifier variant without a
						// nested variant) — skip; the runtime will surface it.
					}
				}
			}
			ts.forEachChild(node, visit);
		};
		visit(source);
	}

	return [...classes];
}

const header =
	"// Generated by pandwind — do not edit. Run `pnpm tw:scan` to regenerate.";

if (process.argv[1]?.endsWith("collect.ts")) {
	const [twEntryArg, srcDirArg, outFileArg] = process.argv.slice(2);
	const base = process.cwd();
	const twEntry = resolve(base, twEntryArg ?? "src/tw.ts");
	const srcDir = resolve(base, srcDirArg ?? "src");
	const outFile = resolve(base, outFileArg ?? "src/pandwind.safelist.ts");

	const classes = await collectTwClasses(walk(srcDir), twEntry);
	const content = `${header}
export const pandwindSafelist = [
${classes.map((className) => `\t${JSON.stringify(className)},`).join("\n")}
] as const;
`;
	writeFileSync(outFile, content);
	console.log(`pandwind: wrote ${classes.length} classes to ${outFile}`);
}
